import type { StoryLocalized } from './catalog';
/** Two passage-grounded dramatized exchanges per Old Testament story. All
 * biblical speech is presented as a CHILD-FRIENDLY PARAPHRASE, not as the
 * exact words of any Bible translation. A teacher conversation can illuminate
 * safety but never changes what a named biblical figure historically said. */
export const BIBLE_EXPANSION_DIALOGUES_OLD: Record<string,readonly [string,string,string,string]> = {
  "paglikha": [
    "Sa pagsasalaysay ng Genesis, ipinahayag ng Diyos ang paglikha ng liwanag. “Magkaroon ng liwanag,” ang diwa ng Kaniyang utos. Unti-unting inilalarawan ng kuwento ang kaayusan: ang liwanag ay hindi na naghalo sa dilim. “Ano kaya ang susunod na lilikhain?” tanong ng batang nakikinig sa guro.",
    "In the Genesis retelling, God commands light to appear: “Let there be light,” in the sense of the passage. The story unfolds with order as light is separated from darkness. “What might God create next?” a listening child wonders.",
    "“Mabuti ang nilikha ng Diyos,” paliwanag ng guro sa klase habang binabanggit ang mga ibon, isda at halaman. “Ibig sabihin po ba na dapat nating alagaan ang mga ito?” tanong ni Liza. “Oo,” sagot ng guro, “may pananagutan ang tao sa nilikha, hindi pahintulot na sirain iyon.”",
    "“God saw that creation was good,” the teacher explains as the story describes birds, fish and plants. “Does that mean we should take care of them?” Liza asks. “Yes,” replies the teacher. “Being entrusted with creation means caring for it, not ruining it.”"
  ],
  "eden": [
    "Sa pagsasadula ng babala, sinabi ng Diyos na malaya silang kumain sa hardin maliban sa ipinagbawal na puno. “Napakarami nating mabubuting bagay dito,” sabi ng isa sa kanilang usapan sa pagsasalaysay. Ang tiwala ay nangangahulugang pakikinig din sa hangganang ibinigay para sa kanila.",
    "In this retelling, God allows the garden's good food but forbids the fruit of one tree. “There is so much good around us already,” one of the pair says in the dramatization. Trust also means respecting a boundary that has been clearly given.",
    "“Talaga bang iyon ang sinabi ng Diyos?” ang hamon ng ahas sa diwa ng Genesis. Nag-alinlangan sina Adan at Eva at piniling sumuway. Nang mapansin nila ang nangyari, hindi na sila maginhawa. “Bakit tayo nagtago?” maituturing na tanong sa ating pagsasadula; ang takot at hiya ay hindi nakapag-alis ng kanilang pananagutan.",
    "“Did God really say that?” is the serpent's challenge in the sense of Genesis. Adam and Eve hesitated and chose disobedience. Afterward they felt uneasy. “Why are we hiding?” is an imagined question in this dramatization; fear and shame could not erase their responsibility."
  ],
  "cain-abel": [
    "“Bakit tila galit na galit si Cain?” tanong ng batang nakikinig. Ipinaliwanag ng guro na magkapatid sila ni Abel at magkakaiba ang kanilang mga handog. Sa salaysay, kinausap ng Diyos si Cain tungkol sa galit at pagpiling gumawa ng tama. Hindi dapat hayaang ang inggit ang magdikta ng kilos.",
    "“Why is Cain so angry?” a child asks. The teacher explains that Cain and Abel were brothers who brought different offerings. In the biblical account, God addresses Cain's anger and his responsibility to choose what is right. Jealousy should never control our actions.",
    "“Nasaan ang iyong kapatid?” ang diwa ng tanong ng Diyos kay Cain. Hindi mababawi ng isang palusot ang ginawang pananakit. “Kapag sobra ang galit ko,” sabi ng batang nakikinig, “lalayo muna ako at magsasabi sa nakatatanda.” Sumagot ang guro, “Iyan ang mas ligtas at makataong pagpili.”",
    "“Where is your brother?” reflects God's question to Cain. An excuse cannot undo violence. “When I feel overwhelmed by anger,” a child says, “I can step away and speak to a trusted adult.” “That is a safer, kinder choice,” the teacher answers."
  ],
  "babel": [
    "“Gumawa tayo ng pangalang magiging tanyag!” ang diwa ng sinabi ng mga tagapagtayo sa Genesis. Sama-sama nilang itinataas ang tore, ngunit hindi lamang pagtatayo ang layunin nila. “Bakit kaya gusto nilang magpasikat?” tanong ng bata. “Minsan,” sagot ng guro, “nakakalimutan natin kung para kanino ang ating kakayahan.”",
    "“Let us make a name for ourselves!” captures the builders' ambition in Genesis. They worked together, yet their purpose was not simply building. “Why did they want to be famous?” asks a child. “Sometimes,” the teacher says, “we forget who our abilities should serve.”",
    "Nang hindi na magkakaunawaan ang mga manggagawa, nagulo ang kanilang plano. “Ano ang sinasabi mo?” maaaring itanong ng isa sa ating pagsasadula. “Hindi kita maintindihan,” sagot ng kasama. Ipinaaalala ng tagpong ito na mahalaga ang pag-unawa at pagpapakumbaba, hindi lamang ang mataas na gusali.",
    "When the workers could no longer understand each other, their plan faltered. “What are you saying?” one may ask in this dramatization. “I can't understand you,” another replies. The scene reminds children that understanding and humility matter more than a tall building."
  ],
  "abraham-tawag": [
    "Sa diwa ng Genesis 12, inanyayahan ng Diyos si Abram na umalis sa kaniyang lupain at tumungo sa lugar na ipapakita Niya. “Hindi ko pa alam ang buong daan,” maaaring sinabi ni Abram sa pagsasadula. “Maghahanda tayo nang mabuti,” sagot ni Sarai, “at maglalakbay kasama ng ating sambahayan.”",
    "In the sense of Genesis 12, God calls Abram to leave his country for a land God will show him. “I do not know the whole road yet,” Abram might say in this dramatization. “We will prepare carefully,” Sarai replies, “and journey with our household.”",
    "“Paano kung mahirap ang paglalakbay?” tanong ng isang kasamang manlalakbay sa pagsasadula. “Hindi sinabi ng pangako na wala nang pagsubok,” tugon ni Abram. Ang tiwala ay lumalakad nang may paghahanda, pakikinig at pag-aalaga sa mga taong kasama sa daan.",
    "“What if the journey is difficult?” an imagined traveling companion asks. “The promise never meant there would be no challenges,” Abram answers in this retelling. Faith is shown through preparation, careful listening and caring for everyone on the journey."
  ],
  "abraham-bituin": [
    "Sa gabing puno ng bituin, ipinakita ng Diyos kay Abraham ang langit at inilarawan ang dami ng magiging lahi niya. “Hindi ko po mabilang ang mga bituin,” sabi ng batang nakikinig sa kuwento. “Ganiyan ipinakita ang lawak ng pangako,” paliwanag ng guro, “kahit hindi pa nakikita ni Abraham kung paano ito mangyayari.”",
    "Under a sky full of stars, God points Abraham to the heavens as an image of his descendants. “I cannot count all those stars,” a child listening to the lesson says. “That shows how vast the promise sounded,” the teacher explains, “even before Abraham knew how it could happen.”",
    "“Napakatagal na nating naghihintay,” maaaring naitanong ni Sara sa pagsasadula. “Nauunawaan kong mahirap,” sagot ni Abraham. Hindi nila hawak ang panahon ng pagtupad. Sa pagdating ng balitang magkakaanak sila, ang pag-aalinlangan at pagtataka ay napalitan ng pag-asang may halong saya.",
    "“We have waited for so long,” Sarah might say in the dramatization. “I know this has been difficult,” Abraham answers. They could not control the timing. When the news of a child came, their surprise and uncertainty made room for hope and joy."
  ],
  "isaac-rebekah": [
    "“Paano ko makikilala ang taong may mabuting puso?” maingat na nanalangin ang lingkod sa kaniyang paglalakbay sa diwa ng Genesis 24. Sa balon, kusang nag-alok si Rebekah ng tubig. “Uminom po kayo,” sabi niya sa pagsasalaysay, “at tutulungan ko rin ang mga kamelyo.” Ipinakita niya ang kabaitan sa gawa.",
    "“How will I recognize a person of kindness?” the servant prays in the sense of Genesis 24. At the well, Rebekah freely offers water. “Please drink,” she says in this retelling, “and I will water the camels too.” Her kindness is shown through an action, not merely a promise.",
    "“Handa ka bang sumama?” tanong ng pamilya kay Rebekah ayon sa salaysay. Hindi basta siya kinuha nang walang pasiya. “Sasama ako,” ang diwa ng sagot niya. Itinuro ng guro sa mga bata na mahalagang igalang ang desisyon at kaligtasan ng bawat taong kasangkot sa isang malaking pagbabago.",
    "“Will you go?” Rebekah's family asks in the biblical account. Her choice is not simply ignored. “I will go,” she answers in the sense of the text. The teacher reminds children that important decisions require respect for the person involved and for their safety."
  ],
  "esau-jacob": [
    "“Bigyan mo ako ng pagkain,” ang hiling ni Esau sa diwa ng Genesis nang siya ay pagod. Sinamantala ni Jacob ang pagkakataon upang ipagpalit ang karapatan ng panganay. “Makatarungan ba ang paggamit sa pangangailangan ng kapatid?” tanong ng guro. “Hindi po,” sagot ng klase, “dapat may malasakit.”",
    "“Give me some of that food,” Esau asks in the sense of Genesis when he is exhausted. Jacob uses the moment to bargain for the birthright. “Is it fair to take advantage of your brother's need?” the teacher asks. “No,” the class answers. “We should show care.”",
    "Pagkaraan ng maraming taon, natakot si Jacob sa muling pagkikita nila. “Paano kung galit pa rin siya?” maaaring naisip niya sa pagsasadula. Ngunit sinalubong siya ni Esau. “Hindi madaling ibalik ang tiwala,” paliwanag ng guro, “at ang tunay na pagkakasundo ay may pagpapakumbaba at paggalang sa hangganan.”",
    "Many years later, Jacob fears seeing his brother again. “What if he is still angry?” he might wonder in this dramatization. Yet Esau comes to meet him. “Trust is not always restored quickly,” the teacher explains. “Real reconciliation requires humility and respect for boundaries.”"
  ],
  "hagdan-jacob": [
    "Sa panaginip, nakita ni Jacob ang hagdang umaabot sa langit at mga anghel na umaakyat at bumababa. Sa diwa ng pangako ng Diyos, “Kasama mo Ako sa iyong paglalakbay.” “Kahit mag-isa po siya sa daan?” tanong ng bata. “Oo,” sagot ng guro, “ito ang pag-asang ipinahayag sa kaniya.”",
    "In his dream, Jacob sees a stairway reaching heaven with angels ascending and descending. God's promise conveys, “I am with you on your journey.” “Even though he is traveling alone?” a child asks. “Yes,” the teacher says. “That is the hope given to him.”",
    "Pagkagising, namangha si Jacob sa kaniyang naranasan. “Hindi ko alam na mahalaga ang lugar na ito,” ang diwa ng kaniyang pahayag. Nagtayo siya ng batong alaala. “Maaari rin ba tayong magpasalamat sa gitna ng pag-aalala?” tanong ng bata. “Maaari,” sagot ng guro, “at maaari ring humingi ng tulong sa tao.”",
    "Jacob awakes astonished. “I did not know this place mattered so much,” expresses his realization. He marks the place with a stone. “Can we still give thanks when we're worried?” a child asks. “We can,” says the teacher, “and we may also ask other people for help.”"
  ],
  "joseph-panaginip": [
    "“Nanaginip ako,” sabi ni Jose sa kaniyang mga kapatid sa pagsasalaysay ng Genesis. Hindi iyon naging magaan pakinggan sa isang pamilyang may paboritismo. “Masakit po ba kapag parang may paborito ang magulang?” tanong ng bata. “Oo,” tugon ng guro, “kaya mahalaga ang patas na pagtrato at pakikinig.”",
    "“I had a dream,” Joseph tells his brothers in the Genesis account. It was difficult to hear in a family already struggling with favoritism. “Can it hurt when one child seems to be preferred?” a child asks. “Yes,” the teacher says. “Fairness and listening matter.”",
    "“Parang naniniwala kang mas mataas ka sa amin!” ang diwa ng inis ng mga kapatid. Hindi naayos ang tampuhan. “Paano sana sila makapag-usap?” tanong ng guro. “Maaari pong sabihin ang sakit na nararamdaman nang hindi nananakit,” sagot ng mga bata.",
    "“Do you think you will rule over us?” captures the brothers' angry reaction. Their conflict grew instead of healing. “How might they have talked more safely?” the teacher asks. “They could explain that they feel hurt without hurting someone else,” the children answer."
  ],
  "joseph-egipto": [
    "“Nasaan na kaya ang aking pamilya?” maaaring naisip ni Jose sa ating pagsasadula habang malayo siya sa tahanan. Ang ginawa sa kaniya ay mali, at hindi niya iyon pinili. “Hindi dapat sinisisi ang batang nasaktan,” sabi ng guro sa klase. “Kailangan niya ng proteksiyon at mga taong maaasahan.”",
    "“Where is my family now?” Joseph might wonder in this dramatization, far from home. What happened to him was wrong and was not his choice. “We must never blame a child who has been harmed,” the teacher tells the class. “That child deserves protection and trustworthy help.”",
    "Sa diwa ng panaginip ng Faraon, magkakaroon ng mga taon ng kasaganaan at pagkatapos ay taggutom. “Ano ang dapat gawin sa pagkaing mayroon tayo?” tanong ng hari sa pagsasalaysay. “Maghanda at mag-imbak nang matalino para sa mga taong kulang,” ang paliwanag ni Jose. Ang karunungan ay ginamit upang maraming mabuhay.",
    "Pharaoh's dreams indicate years of abundance followed by famine. “What should we do with the food we have?” the ruler asks in this retelling. “Plan carefully and store enough for the years of scarcity,” Joseph explains. His skill is used to help many people survive."
  ],
  "joseph-patawad": [
    "“Parang kilala ko ang mga taong ito,” maaaring naisip ni Jose nang makita ang kaniyang mga kapatid. Hindi nila siya nakilala. “Paano kung ikaw ang nasaktan dati?” tanong ng guro. “Hindi ko kailangang magkunwaring walang nangyari,” sagot ng bata. “Tama,” paliwanag ng guro, “mahalaga rin ang kaligtasan.”",
    "“I recognize these people,” Joseph might think as his brothers stand before him. They do not recognize him. “What if someone once hurt you?” a teacher asks. “I don't have to pretend nothing happened,” a child replies. “Exactly,” the teacher says. “Safety still matters.”",
    "“Ako si Jose,” ang diwa ng kaniyang pagkakilala sa mga kapatid. Natakot sila ngunit hindi niya ginamit ang kapangyarihan upang gumanti. “Hindi mabuti ang ginawa ninyo,” ipinapakita ng kuwento, “ngunit maaari nating piliing huwag ipagpatuloy ang pananakit.” Hindi nangangahulugan ang pagpapatawad na kailangang mawala ang malusog na hangganan.",
    "“I am Joseph,” he reveals himself to his brothers in the sense of Genesis. They are afraid, yet he does not use his power to take revenge. The story says, in effect, “What you did was wrong, but harm does not need to continue.” Forgiveness never requires someone to abandon healthy boundaries."
  ],
  "baby-moses": [
    "“Kailangan nating protektahan si Moises,” ang maingat na hangarin ng kaniyang ina sa pagsasadula. Pinili ng pamilya ang mga hakbang na kaya nilang gawin sa gitna ng panganib. “Malaking tulong po ba ang kaniyang kapatid?” tanong ng bata. “Oo,” sagot ng guro, “nagbantay siya at nag-isip nang mabilis.”",
    "“We must keep Moses safe,” is his mother's careful intention in this dramatization. The family does what it can amid danger. “Did his sister really help?” a child asks. “Yes,” the teacher answers. “She watched closely and thought quickly.”",
    "Nang makita ng anak ng Faraon ang sanggol, naawa siya. Sa pagsasadula, magalang na nagtanong ang kapatid ni Moises: “Maaari po ba akong maghanap ng mag-aalaga sa bata?” Ang kaniyang matalinong pagsasalita ay nakatulong upang mapalapit muli ang sanggol sa sariling pamilya sa loob ng isang mapanganib na panahon.",
    "When Pharaoh's daughter finds the baby, she is moved with compassion. In the dramatization, Moses' sister asks respectfully, “Shall I find someone to nurse the child?” Her thoughtful words help bring the baby back into his family's care during a dangerous time."
  ],
  "naglalagablab-puno": [
    "“Moises, Moises,” ang diwa ng tawag ng Diyos mula sa palumpong sa Exodus 3. “Narito ako,” ang sagot ni Moises sa salaysay. Napansin niya na nasusunog ang halaman ngunit hindi nauubos. “Bakit kaya siya huminto?” tanong ng bata. “Nagdulot ito ng pagtataka at paggalang,” sagot ng guro.",
    "“Moses, Moses,” God calls from the bush in Exodus 3. “Here I am,” Moses answers in the passage. The bush burns without being consumed. “Why did Moses stop?” a child asks. “The sight filled him with wonder and reverence,” the teacher replies.",
    "“Sino ako upang harapin ang Faraon?” ang diwa ng pag-aalinlangan ni Moises. Sa utos ng Diyos, malalaman niyang hindi siya pinababayaan. “Hindi po ba maaaring humingi ng katuwang?” tanong ng bata. “Maaari,” sagot ng guro, “at tinulungan si Moises sa pamamagitan ni Aaron.”",
    "“Who am I to go to Pharaoh?” captures Moses' doubts. In God's call, Moses is assured he will not be abandoned. “May he ask for help?” a child asks. “Yes,” says the teacher. “Aaron was given to help him.”"
  ],
  "sampung-salot": [
    "“Palayain mo ang aking bayan,” ang diwa ng mensaheng ibinigay kina Moises at Aaron para kay Faraon. Ngunit tumanggi ang hari. “Bakit po kailangang maulit ang babala?” tanong ng bata. “Dahil patuloy ang pang-aapi,” paliwanag ng guro, “at mabigat ang pasiya ng makapangyarihan.”",
    "“Let my people go,” conveys the message Moses and Aaron carry to Pharaoh. The ruler refuses. “Why was the warning repeated?” a child asks. “Because oppression continued,” the teacher explains. “Those in power bear a heavy responsibility for their choices.”",
    "“Natatakot na ang mga pamilya,” maingat na sabi ng guro sa pagsasalaysay ng mabibigat na salot. Hindi ipinagdiriwang ang pagdurusa. “Ano ang dapat nating alalahanin?” tanong ng bata. “Mahalaga ang buhay at kalayaan,” sagot ng guro, “at hindi natin ginagaya ang pananakit.”",
    "“Families must have been frightened,” the teacher says gently while describing the severe plagues. Suffering is not a game to celebrate. “What should we remember?” a child asks. “Life and freedom matter,” the teacher answers, “and we do not imitate harm.”"
  ],
  "paskuwa": [
    "“Bakit kakaiba ang hapunan natin?” maaaring tanungin ng batang Israelita sa pagsasadula. “May tiyak na tagubilin tayong susundin ngayong gabi,” paliwanag ng magulang. Ginagamit ang tagpong ito upang ipaliwanag ang paghahanda, hindi upang palitan ang mismong mga salita ng Exodus 12.",
    "“Why is tonight's meal different?” an Israelite child might ask in the dramatization. “We have specific instructions to follow this evening,” the parent explains. This scene helps children understand preparation without replacing the words of Exodus 12.",
    "“Kapag lumaki ako, aalalahanin ko rin ba ang gabing ito?” tanong ng bata sa ating pagsasadula. “Oo,” sagot ng magulang, “ito ang kuwento ng pag-alis natin mula sa pagkaalipin.” Ang Paskuwa ay paggunita ng Israel, kaya mahalagang ikuwento ito nang may paggalang sa kasaysayan at tradisyon.",
    "“When I grow up, will I remember this night too?” a child asks in our dramatization. “Yes,” the parent replies. “It is part of the story of our people's release from slavery.” Passover is Israel's remembrance, so its history and tradition deserve respectful explanation."
  ],
  "dagat-pula": [
    "“Nasa likod natin ang mga humahabol!” ang takot na maaaring marinig sa isang pamilyang Israelita. “At ang dagat ay nasa harap,” sagot ng isa sa ating pagsasadula. Sa salaysay, sinabi ni Moises na magtiwala sa pagliligtas ng Diyos. Hindi niya itinago ang panganib ng kanilang kalagayan.",
    "“The pursuers are behind us!” voices the fear of an Israelite family. “And the sea is ahead,” another answers in this dramatization. In the biblical account, Moses urges the people to trust God's deliverance. Their danger is not minimized.",
    "“Ligtas na kaya tayo?” tanong ng batang nakikinig habang inilalarawan ang pagtawid. “Natatanging pagliligtas ito sa Exodus,” sagot ng guro. “Sa totoong baha o dagat, hindi natin susubukang gayahin iyon. Makikinig tayo sa babala at sa mga tagapagligtas.”",
    "“Are they safe now?” a listening child asks as the crossing is described. “This is an extraordinary deliverance in Exodus,” the teacher says. “In a real flood or sea, we do not try to copy it. We listen to safety warnings and rescuers.”"
  ],
  "manna": [
    "“Ano ang kakainin natin ngayon?” tanong ng isang nagugutom na pamilya sa ating pagsasadula. Sa salaysay, nagbigay ang Diyos ng manna sa umaga. “Ano ito?” ang diwa ng pagtataka ng mga Israelita. Hindi ito karaniwang pagkain na nakilala nila noon.",
    "“What will we eat today?” an imagined hungry family asks. In the account, God provides manna in the morning. “What is it?” captures the Israelites' surprise. This was not food they had known before.",
    "“Dapat ba nating kunin ang sobra-sobra para sa atin lamang?” tanong ng bata. “May tagubiling kumuha ng kailangan, at alalahanin ang araw ng pahinga,” sagot ng guro. “Kapag may sapat tayo at may kapitbahay na nagugutom, maaari rin tayong magbahagi nang may pag-iingat.”",
    "“Should we gather far more than we need?” a child asks. “They were instructed to collect enough and remember the day of rest,” says the teacher. “When we have enough and a neighbor is hungry, we can also share responsibly.”"
  ],
  "sampung-utos": [
    "Sa Bundok Sinai, inilahad ng Diyos ang mga utos para sa buhay ng bayan. “Bakit po mahalaga ang utos na huwag magsinungaling?” tanong ng bata. “Dahil nasisira ang tiwala kapag hindi totoo ang sinasabi,” sagot ng guro. Ang mga utos ay tumutulong sa tamang pakikitungo.",
    "At Sinai, God gives commandments for the life of the people. “Why does the command not to lie matter?” a child asks. “Because falsehood damages trust,” the teacher answers. The commandments guide the way people treat one another.",
    "“Paano ko maipapakita ang paggalang sa magulang?” tanong ng bata. “Makinig, maging magalang, at magsabi kung may bagay na hindi ligtas,” paliwanag ng guro. “Ang paggalang ay hindi nangangahulugang dapat mong sundin ang isang utos na mananakit sa iyo o sa iba.”",
    "“How can I show respect to my parents?” asks a child. “Listen, speak respectfully, and tell someone if something is unsafe,” the teacher explains. “Respect never means you must obey a command that would hurt you or someone else.”"
  ],
  "guya-ginto": [
    "“Matagal nang wala si Moises,” ang reklamo ng mga taong naghihintay. “Gumawa tayo ng bagay na maaari nating sundan,” ang kanilang maling pasiya sa diwa ng Exodus 32. “Bakit po kaya nakisunod ang iba?” tanong ng bata. “Minsan, pinipili ng tao ang madali kahit mali,” sagot ng guro.",
    "“Moses has been gone a long time,” the waiting people complain. “Let us make something to follow,” captures their wrong decision in Exodus 32. “Why did others join in?” a child asks. “Sometimes people choose what is easy even when it is wrong,” the teacher says.",
    "Pagbalik ni Moises, nakita niya ang kanilang pagsamba sa ginintuang guya. “Hindi po ba nila naalala ang ipinangako nila?” tanong ng bata. “Nadala sila ng takot at panggagaya,” paliwanag ng guro. “Mahalagang magtanong at tumanggi kapag ang grupo ay may ginagawang mali.”",
    "When Moses returns, he sees them worshiping the golden calf. “Didn't they remember their promise?” a child asks. “Fear and pressure from the crowd influenced them,” the teacher answers. “It matters to ask questions and say no when a group chooses wrong.”"
  ],
  "tolda-pagsamba": [
    "“Marunong akong gumawa ng tela,” sabi ng isa sa mga manggagawa sa pagsasadula. “Ako naman ang may kakayahan sa kahoy,” tugon ng isa. Bawat handog at kasanayan ay may lugar sa tabernakulo. “Puwede rin po ba ang maliit na tulong?” tanong ng bata. “Oo, kapag kusang-loob at maingat,” sagot ng guro.",
    "“I know how to weave,” one worker says in the dramatization. “I can work with wood,” another replies. Different skills help build the tabernacle. “Does a small contribution matter too?” a child asks. “Yes, when it is willing and thoughtful,” says the teacher.",
    "“Sapat na ang mga handog,” ang diwa ng ulat ng mga manggagawa sa Exodus. Hindi kailangang manghingi nang walang katapusan. “Ibig sabihin po ba na hindi dapat pilitin ang magbigay?” tanong ng bata. “Tama,” sagot ng guro. “Ang paglilingkod ay may paggalang sa kakayahan at kalagayan ng bawat isa.”",
    "“There is enough,” reflects the workers' report in Exodus. Giving did not need to continue endlessly. “So people should not be pressured to give?” a child asks. “Exactly,” the teacher says. “Service should respect each person's circumstances and ability.”"
  ],
  "labindalawang-espiya": [
    "“Masagana ang lupain,” ulat ng mga tagapagmasid, “ngunit may malalakas na pamayanan doon.” Magkaiba ang naging pagtugon sa kanilang nakita. “Ano ang pagkakaiba ng pag-uulat at pananakot?” tanong ng bata. “Ang tapat na ulat ay may buong larawan,” paliwanag ng guro.",
    "“The land is fruitful,” the scouts report, “but there are strong communities there.” Their responses differ. “What is the difference between reporting and frightening people?” a child asks. “An honest report presents the whole picture,” the teacher explains.",
    "Sa diwa ng sinabi nina Josue at Caleb, hindi dapat hayaang ang takot lamang ang magpasiya. “Paano po natin malalaman kung may totoong panganib?” tanong ng bata. “Makinig sa tamang impormasyon at humingi ng gabay,” sagot ng guro, “hindi magpadalos-dalos at hindi rin tumanggi dahil lang natakot.”",
    "In the sense of Joshua and Caleb's appeal, fear alone should not make every decision. “How can we recognize real danger?” a child asks. “Listen to reliable information and seek wise guidance,” the teacher answers. “Neither rush recklessly nor refuse solely from fear.”"
  ],
  "balaam-asno": [
    "Paulit-ulit na huminto ang asno ni Balaam dahil may nakita itong hindi niya napapansin. “Bakit ayaw mo nang magpatuloy?” ang inis ni Balaam sa pagsasadula. Sa salaysay, nakapagsalita ang asno. Hindi ito ordinaryong pangyayari, kundi natatanging bahagi ng kuwento sa Bilang 22.",
    "Balaam's donkey stops again and again because it sees something Balaam does not. “Why won't you go on?” Balaam complains in the dramatization. In the biblical account the donkey speaks. This is an extraordinary event in Numbers 22, not an ordinary animal behavior.",
    "“Hindi mo ba nakita ang panganib?” ang diwa ng pagtutuwid na naranasan ni Balaam. “Kapag nagalit ako sa alagang hayop,” tanong ng bata, “ano ang dapat kong gawin?” “Huminto, tingnan kung may dahilan ito, at huwag manakit,” sagot ng guro.",
    "“Did you not see the danger?” conveys the correction Balaam receives. “When I get upset with an animal,” a child asks, “what should I do?” “Stop, check for a reason, and never respond with cruelty,” the teacher answers."
  ],
  "jordan": [
    "“Malakas ang agos ng Jordan,” napansin ng bayan sa pagsasadula. Pinangunahan ni Josue ang pagtawid ayon sa tagubilin ng Diyos. “Mahirap kayang manguna kapag bago kang pinuno?” tanong ng bata. “Oo,” paliwanag ng guro, “kaya mahalaga ang mabuting gabay at pananagutan.”",
    "“The Jordan is overflowing,” the people observe in this dramatization. Joshua leads the crossing according to God's instruction. “Is leading difficult when you are new?” a child asks. “Yes,” the teacher explains. “Good guidance and responsibility matter.”",
    "“Bakit tayo naglagay ng labindalawang bato?” ang tanong na inilalarawan sa Josue 4. “Upang maalala ng mga susunod na bata ang nangyari,” paliwanag ng magulang sa ating pagsasalaysay. Ang mga tanda ng alaala ay paanyayang magtanong at makinig sa kasaysayan.",
    "“Why did we place twelve stones here?” is the kind of question described in Joshua 4. “So future children can remember what happened,” a parent explains in this retelling. Memorials invite people to ask questions and listen to their history."
  ],
  "jerico": [
    "“Iikot tayo sa lungsod ayon sa tagubilin,” ang diwa ng bilin ni Josue sa sinaunang salaysay. Hindi pa nakikita ng bayan kung paano babagsak ang pader. “Bakit po kakaiba ang paraan?” tanong ng batang nakikinig. “Natatangi ang pangyayaring ito,” sagot ng guro, “at may konteksto itong digmaan.”",
    "“We will march around the city as instructed,” conveys Joshua's direction in the ancient account. The people cannot yet see how the walls will fall. “Why is the plan unusual?” a child asks. “This event is exceptional,” the teacher answers, “and it belongs to an ancient war.”",
    "Nang tumunog ang mga trumpeta, nagsigawan ang bayan at bumagsak ang pader sa salaysay. “Maaari po ba itong gawing laro ng pananakop?” tanong ng bata. “Hindi,” sagot ng guro. “Hindi natin ginagaya ang karahasan. Ang buhay ng tao ay mahalaga, at pinipili natin ang kapayapaan.”",
    "When trumpets sound, the people shout, and the wall falls in the account. “Can we turn this into a game about hurting others?” a child asks. “No,” the teacher says. “We do not copy violence. Human life matters, and we choose peace.”"
  ],
  "rahab": [
    "“Tulungan mo kaming makalabas nang ligtas,” ang diwa ng pangangailangan ng mga tagapagmasid sa pagsasadula. Pinag-isipan ni Rahab ang panganib. “Maaari ko bang hilinging iligtas din ang aking pamilya?” ang diwa ng kaniyang pakikipagkasundo. Hindi niya kinalimutan ang mga mahal sa buhay.",
    "“Help us get out safely,” captures the scouts' need in the dramatization. Rahab weighs the danger. “May I ask that my family be protected as well?” conveys her request in the biblical account. She does not forget those she loves.",
    "“Ano ang ibig sabihin ng pulang lubid sa bintana?” tanong ng bata. “Tanda iyon ng napagkasunduan sa kuwentong ito,” paliwanag ng guro. “Huwag nating gawing mahiwagang anting-anting. Ang mahalagang aral ay ang pagtupad sa pangako at pagprotekta sa buhay.”",
    "“What does the red cord in the window mean?” a child asks. “It marks an agreement in this story,” the teacher explains. “It is not a magical charm. The important lessons are keeping promises and protecting life.”"
  ],
  "deborah": [
    "“May mga taong nangangailangan ng makatarungang paghatol,” ang paliwanag ni Deborah sa ating pagsasadula habang nakikinig sa mga lumalapit sa kaniya. “Bakit po lumalapit sila sa isang babae?” tanong ng bata. “Dahil kinilala ang kaniyang karunungan at pamumuno,” sagot ng guro.",
    "“People need fair judgments,” Deborah explains in our dramatization as she listens to those who come to her. “Why did people come to a woman leader?” a child asks. “Because her wisdom and leadership were recognized,” the teacher replies.",
    "“Sasama ka ba sa akin?” ang diwa ng hiling ni Barak sa Judges 4. “Sasama ako,” tugon ni Deborah sa salaysay. Ang pakikipagtulungan ay hindi pagtago sa pananagutan. “Kapag mahirap ang tungkulin,” paliwanag ng guro, “maaaring humingi ng katuwang at kumilos nang may karunungan.”",
    "“Will you go with me?” reflects Barak's request in Judges 4. “I will go,” Deborah answers in the account. Working together does not erase responsibility. “When a task is hard,” the teacher explains, “we may ask for support and act wisely.”"
  ],
  "gideon": [
    "“Kung kasama natin ang Diyos, bakit tayo nahihirapan?” ang diwa ng mga tanong ni Gideon sa Hukom 6. Natatakot siya sa mga mananalakay. “Masama po bang magtanong kapag natatakot?” usisa ng bata. “Hindi,” sagot ng guro, “maaaring ilahad ang takot at humingi ng gabay.”",
    "“If God is with us, why have we suffered?” conveys Gideon's questions in Judges 6. He is frightened by the raiders. “Is it wrong to ask questions when afraid?” a child wonders. “No,” the teacher replies. “We can name fear and seek guidance.”",
    "“Napakaliit na ng ating pangkat,” maaaring naisip ni Gideon sa pagsasadula nang mabawasan ang hukbo. Hindi ipinagmalaki ng kuwento ang dami ng armas. “Puwede po ba nating tularan ang panlilinlang sa digmaan?” tanong ng bata. “Hindi,” sagot ng guro. “Maghanap tayo ng mapayapang paraan ng paglutas sa alitan.”",
    "“Our group has become so small,” Gideon might think in this dramatization as the army is reduced. The account does not glorify weapons alone. “Should we copy war tactics?” a child asks. “No,” the teacher says. “We should seek peaceful ways to resolve conflict.”"
  ],
  "samson": [
    "“Malakas si Samson,” sabi ng batang nakikinig, “pero bakit may maling desisyon pa rin siya?” Ipinaliwanag ng guro na ang pambihirang lakas ay hindi kapalit ng pagpipigil sa sarili. Sa pagsasadula, maaaring paalalahanan siya ng kaibigan: “Isipin mo muna ang magiging bunga bago ka kumilos.”",
    "“Samson is strong,” a child says, “so why does he still make bad choices?” The teacher explains that extraordinary strength is not a substitute for self-control. In a dramatization, a friend might warn him, “Think about the consequences before acting.”",
    "Nang mawalan ng kalayaan si Samson, nakita ang bigat ng mga maling pasiya. “Maaari pa po bang humingi ng tulong kapag nagkamali?” tanong ng bata. “Oo,” sabi ng guro, “ngunit maaaring may mga pinsalang hindi na mababawi. Ang tapang ay mas mabuting gamitin sa pag-iingat kaysa pananakit.”",
    "When Samson loses his freedom, the consequences of his choices become clear. “Can someone still ask for help after making mistakes?” a child asks. “Yes,” the teacher says, “but some harm cannot be undone. Strength is better used for protection than violence.”"
  ],
  "ruth-naomi": [
    "“Saan ka pupunta, sasama ako,” ang diwa ng pangako ni Ruth kay Naomi sa Ruth 1. Nagluluksa silang dalawa, ngunit ayaw niyang pabayaang mag-isa ang kaniyang biyenan. “Mahirap po bang umalis sa sariling bayan?” tanong ng bata. “Oo,” sagot ng guro, “kaya mahalaga ang kasama at paggalang.”",
    "“Where you go, I will go,” conveys Ruth's promise to Naomi in Ruth 1. Both are grieving, and Ruth refuses to abandon her mother-in-law. “Is leaving home difficult?” a child asks. “It can be,” says the teacher. “Support and respect matter.”",
    "“Maaari po ba akong mamulot ng mga naiwang uhay?” ang magalang na hangarin ni Ruth sa bukid sa pagsasadula. Tiniyak ni Boaz na may ligtas siyang lugar na pagtatrabahuhan. “Bakit po mahalaga iyon?” tanong ng bata. “Dahil ang kabaitan ay may proteksiyon sa mahihina,” sagot ng guro.",
    "“May I gather the leftover grain?” Ruth asks respectfully in this dramatization. Boaz helps ensure she has a safe place to work. “Why is that important?” a child asks. “Because kindness must include protection for people who are vulnerable,” the teacher says."
  ],
  "samuel-tinawag": [
    "“Samuel!” ang tawag sa kaniyang pangalan sa gabi. “Narito po ako,” ang tugon niya habang pumupunta kay Eli. Ilang beses itong naulit. “Bakit po hindi agad niya naunawaan?” tanong ng bata. “Bata pa siya at natututo pang makinig at magtanong,” paliwanag ng guro.",
    "“Samuel!” comes the call at night. “Here I am,” he answers as he goes to Eli. It happens more than once. “Why didn't he understand right away?” a child asks. “He was young and learning how to listen and ask for guidance,” the teacher explains.",
    "Sa diwa ng payo ni Eli, “Magsalita Ka, Panginoon; nakikinig ang Iyong lingkod.” Natutuhan ni Samuel na maging matapat sa mahirap na mensahe. “Kung may magsasabing may lihim na utos sa akin,” tanong ng bata, “sino ang kakausapin ko?” “Isang mapagkakatiwalaang nakatatanda,” sagot ng guro.",
    "In the sense of Eli's advice, “Speak, Lord; your servant is listening.” Samuel learns to be truthful even with a hard message. “If someone claims a secret command for me,” a child asks, “who should I talk to?” “A trusted adult,” the teacher answers."
  ],
  "saul-hari": [
    "“Gusto namin ng hari tulad ng ibang bayan,” ang hiling ng mga Israelita sa diwa ng 1 Samuel 8. Ipinaliwanag ni Samuel na may kaakibat na panganib ang kapangyarihan. “Bakit po kailangang magtanong bago pumili ng pinuno?” tanong ng bata. “Dahil maaapektuhan ang maraming buhay,” sagot ng guro.",
    "“We want a king like the other nations,” the Israelites ask in the sense of 1 Samuel 8. Samuel warns them that power carries risks. “Why must we think carefully before choosing a leader?” a child asks. “Because many lives are affected,” the teacher replies.",
    "Nang maging hari si Saul, nagkaroon siya ng pagkakataong maglingkod nang maayos. Ngunit hindi laging naging tapat ang kaniyang mga pasiya. “Sapat na po ba ang pagiging sikat?” tanong ng bata. “Hindi,” sagot ng guro. “Ang tunay na pamumuno ay sinusukat sa katapatan at pananagutan.”",
    "When Saul becomes king, he has a chance to serve well, but his decisions are not always faithful. “Is being famous enough to lead?” a child asks. “No,” the teacher replies. “Leadership is measured by honesty and responsibility.”"
  ],
  "david-pinili": [
    "“Huwag lang tumingin sa panlabas na anyo,” ang diwa ng tagubilin ng Diyos kay Samuel sa 1 Samuel 16. Nakita ng propeta ang matatangkad na mga anak ni Jesse. “Kung hindi po sa tangkad, saan?” tanong ng bata. “Sa puso at pagkatao,” paliwanag ng guro.",
    "“Do not judge by outward appearance alone,” conveys God's guidance to Samuel in 1 Samuel 16. The prophet sees Jesse's tall sons. “If not height, what should matter?” a child asks. “A person's heart and character,” the teacher answers.",
    "“May isa pa akong anak na nag-aalaga ng mga tupa,” ang diwa ng sagot ni Jesse. Tinawag nila si David mula sa gawain. “Kahit bunso po siya?” tanong ng bata. “Oo,” sagot ng guro. “Hindi laging ang pinakamalaki o pinakakilala ang may kakayahang maglingkod.”",
    "“There is still a son tending the sheep,” reflects Jesse's answer. David is called in from his work. “Even though he was the youngest?” a child asks. “Yes,” the teacher says. “The biggest or most famous person is not always the one chosen to serve.”"
  ],
  "david-jonathan": [
    "“Kaibigan kita,” ang diwa ng matibay na pagkakaibigan nina Jonathan at David. Nang lumala ang panganib mula kay Saul, hindi naging madali ang paninindigan ni Jonathan. “Maaari po bang maging tapat sa kaibigan kahit hindi sang-ayon ang pamilya?” tanong ng bata. “Maaaring maging mabuti at magalang habang pinoprotektahan ang buhay,” sagot ng guro.",
    "“You are my friend,” expresses the bond between Jonathan and David. When danger from Saul grows, Jonathan faces difficult choices. “Can someone be loyal to a friend even when family disagrees?” a child asks. “We can act kindly and respectfully while protecting someone's life,” the teacher replies.",
    "“Kailangan mong makaalis nang ligtas,” ang diwa ng tulong ni Jonathan kay David sa pagsasadula. Hindi niya tinulungang manakit ang kaibigan; tinulungan niya itong umiwas sa panganib. “Iyan po ba ang tunay na pagkakaibigan?” tanong ng bata. “Oo,” sagot ng guro, “nagmamalasakit sa kapakanan ng isa't isa.”",
    "“You need to get away safely,” reflects Jonathan's help for David in this dramatization. He does not encourage violence; he helps his friend avoid danger. “Is that what real friendship looks like?” a child asks. “Yes,” says the teacher. “It protects each other's well-being.”"
  ],
  "david-saul-awa": [
    "“Ngayon na ang pagkakataon mong gumanti,” ang tukso ng mga kasama ni David sa diwa ng 1 Samuel 24. Ngunit hindi niya ginamit ang pagkakataon upang saktan si Saul. “Bakit po hindi niya ginawa?” tanong ng bata. “Pinili niyang pigilan ang sarili,” sagot ng guro, “kahit may takot at galit.”",
    "“Now is your chance to get even,” reflects the temptation David faces from his companions in 1 Samuel 24. He refuses to hurt Saul. “Why didn't he do it?” a child asks. “He chose self-control,” the teacher answers, “even while he felt fear and anger.”",
    "“Hindi kita sinaktan kahit may pagkakataon,” ang diwa ng ipinakita ni David kay Saul. Hindi ibig sabihin nito na naging ligtas agad ang paligid; kailangan pa ring umiwas ni David. “Kung may nananakot sa akin, kailangan ko bang lumapit muli?” tanong ng bata. “Hindi,” sagot ng guro, “unahin ang kaligtasan.”",
    "“I did not harm you even when I had the chance,” conveys David's action toward Saul. That did not make the situation instantly safe; David still had to keep his distance. “If someone threatens me, must I go back to them?” a child asks. “No,” says the teacher. “Safety comes first.”"
  ],
  "solomon-hatol": [
    "“Bigyan Mo ako ng pusong marunong humatol,” ang diwa ng hiling ni Solomon sa Diyos sa 1 Hari 3. Hindi siya humingi ng mas maraming kayamanan lamang. “Bakit po karunungan ang pinili niya?” tanong ng bata. “Dahil maraming tao ang umaasa sa makatarungang desisyon niya,” sagot ng guro.",
    "“Give me a discerning heart to judge,” conveys Solomon's request to God in 1 Kings 3. He does not simply ask for greater wealth. “Why did he choose wisdom?” a child asks. “Because many people depend on fair decisions from him,” the teacher says.",
    "Nang harapin ang mahirap na usapin ng dalawang ina, nakita ni Solomon kung sino ang handang unahin ang buhay ng sanggol. “Huwag pong saktan ang bata,” ang diwa ng matinding pakiusap ng tunay na ina. “Hindi po talaga dapat subukin iyon sa totoong buhay,” paalala ng guro, “ang aral ay protektahan ang mahina.”",
    "When Solomon faces the case of two women and one child, he learns who is willing to put the baby's life first. “Do not hurt the child,” conveys the real mother's plea. “We must never recreate that kind of test in real life,” the teacher reminds the class. “The lesson is to protect the vulnerable.”"
  ],
  "solomon-templo": [
    "“Marami tayong kailangang itayo,” ang diwa ng pagbabahagi ng mga manggagawa sa panahon ni Solomon. May mga bihasa sa kahoy, bato at metal. “Maaari po bang magawa ng isang tao lamang?” tanong ng bata. “Hindi,” sagot ng guro, “kailangan ang mahusay at maingat na pagtutulungan.”",
    "“There is so much to build,” reflects the workers' task in Solomon's time. Some are skilled in wood, stone and metal. “Could one person have built it all?” a child asks. “No,” the teacher says. “It required many people working carefully together.”",
    "Sa pag-aalay ng templo, kinilala ni Solomon na hindi kayang ikulong ng gusali ang Diyos. “Ibig sabihin po ba na hindi lang sa magandang gusali makikita ang pananampalataya?” tanong ng bata. “Tama,” sagot ng guro. “Mahalaga rin ang katapatan at malasakit kapag wala ka sa lugar ng pagsamba.”",
    "At the dedication, Solomon acknowledges that a building cannot contain God. “So faith isn't shown only in a beautiful building?” a child asks. “That's right,” the teacher replies. “Honesty and compassion matter outside a place of worship too.”"
  ],
  "elijah-ibon": [
    "“Paano kaya ako magkakaroon ng pagkain dito?” ang maaaring naisip ni Elias sa ating pagsasadula. Sa salaysay, may mga uwak na nagdala ng pagkain sa kaniya sa tabi ng batis. “Totoo po bang hindi karaniwan iyon?” tanong ng bata. “Oo,” sagot ng guro, “natatanging bahagi iyon ng kuwentong biblikal.”",
    "“How will I find food here?” Elijah might wonder in our dramatization. In the account, ravens bring him food beside the brook. “Was that unusual?” a child asks. “Very,” says the teacher. “It is an extraordinary part of the biblical story.”",
    "Nang matuyo ang batis, kailangan ni Elias na umalis. “Kung natuyo na ang pinagkukunan ng tubig,” tanong ng bata, “mananatili pa rin ba tayo roon?” “Hindi,” sagot ng guro. “Sa totoong buhay, hihingi tayo ng ligtas na tulong at maghahanap ng maaasahang tubig.”",
    "When the brook dries up, Elijah needs to move on. “If a water source dries up,” a child asks, “should we just stay there?” “No,” the teacher answers. “In real life we seek safe help and a reliable source of drinking water.”"
  ],
  "elijah-balo": [
    "“Kaunti na lang ang harina at langis namin,” ang diwa ng malungkot na sagot ng biyuda kay Elias. “Paano po niya aalagaan ang anak niya?” tanong ng bata. “Napakahirap ng kaniyang sitwasyon,” sabi ng guro. “Kailangan ang malasakit, hindi ang paghusga sa mahihirap.”",
    "“We have only a little flour and oil left,” conveys the widow's sorrowful reply to Elijah. “How will she care for her son?” a child asks. “Her situation is very hard,” the teacher says. “Poor families deserve compassion, not judgment.”",
    "Ayon sa salaysay, hindi naubos ang harina at langis habang may taggutom. “Ibig sabihin po ba na dapat ibigay ng mahirap ang huli niyang pagkain kahit mapanganib?” tanong ng bata. “Hindi,” sagot ng guro. “Huwag pilitin ang sinuman. Ang aral ay pagtulong sa nangangailangan at pagtitiwala na may kasamang pag-iingat.”",
    "In the account, the flour and oil last through the famine. “Does that mean a poor family must give away their last meal even when it is unsafe?” a child asks. “No,” the teacher answers. “Never pressure someone. The lesson is care for people in need, with responsible choices.”"
  ],
  "elijah-carmel": [
    "“Hanggang kailan kayo mag-aalinlangan?” ang diwa ng hamon ni Elias sa 1 Hari 18. Nagtipon ang bayan sa Carmel upang marinig ang kanilang pagtatalo tungkol sa pagsamba. “Bakit po mahalagang alamin ang katotohanan?” tanong ng bata. “Dahil nakaaapekto sa ating mga pasiya ang pinaniniwalaan natin,” sagot ng guro.",
    "“How long will you waver?” reflects Elijah's challenge in 1 Kings 18. The people gather at Carmel to witness a dispute about worship. “Why does truth matter?” a child asks. “Because what we believe affects how we treat others,” the teacher replies.",
    "Nang manalangin si Elias, nagkaroon ng pambihirang sagot na apoy sa salaysay. “Puwede po ba tayong sumubok ng apoy para patunayan ang pananampalataya?” tanong ng bata. “Hinding-hindi,” sagot ng guro. “Hindi natin kinokopya ang mapanganib na sinaunang tagpo. Pinipili natin ang paggalang at kapayapaan.”",
    "When Elijah prays, the account describes an extraordinary answer by fire. “Should we try using fire to prove faith?” a child asks. “Absolutely not,” the teacher responds. “We do not imitate dangerous ancient scenes. We choose respect and peace.”"
  ],
  "elijah-mahinang-tinig": [
    "“Pagod na pagod na ako,” ang damdaming ipinahayag ni Elias sa gitna ng takot. Sa halip na pagalitan agad, binigyan siya ng pahinga at pagkain. “Mahalaga po pala ang pagtulog kapag malungkot?” tanong ng bata. “Oo,” sagot ng guro, “at ang pakikinig at paghingi ng tulong.”",
    "“I am exhausted,” expresses how Elijah feels in his fear and despair. Instead of being rebuked immediately, he receives food and rest. “Does sleep matter when someone feels very sad?” a child asks. “Yes,” says the teacher, “along with being heard and asking for support.”",
    "Dumaan ang hangin, lindol at apoy; pagkatapos ay ang marahang tinig sa salaysay. “Bakit po hindi lang sa malakas na pangyayari naririnig ang mahalaga?” tanong ng bata. “Minsan, kailangan muna nating tumahimik at makinig,” sagot ng guro, “at pahalagahan ang nagmamalasakit sa atin.”",
    "Wind, earthquake and fire pass, followed by a gentle sound in the account. “Why isn't everything important loud?” a child asks. “Sometimes we must be quiet and listen,” the teacher replies, “and value people who care for us.”"
  ],
  "naaman": [
    "“May propeta sa Samaria na maaaring lapitan,” ang balita ng batang babaeng tumutulong sa pamilya ni Naaman sa 2 Hari 5. “Bakit po mahalaga ang kaniyang tinig?” tanong ng bata. “Kahit bata at walang mataas na posisyon, may mahalagang bagay siyang naibahagi,” sagot ng guro.",
    "“There is a prophet in Samaria who may be able to help,” says the young servant girl in 2 Kings 5. “Why does her voice matter?” a child asks. “Even someone young and without status can offer important knowledge,” the teacher explains.",
    "“Bakit sa Jordan pa?” ang diwa ng inis ni Naaman nang marinig ang payo ni Eliseo. Hinimok siyang makinig ng kaniyang mga lingkod. “Kapag may sakit po ako, sapat na ang pagligo?” tanong ng bata. “Hindi,” sagot ng guro. “Magpatingin sa lisensiyadong propesyonal; ito ay natatanging kuwento ng pananampalataya.”",
    "“Why the Jordan?” captures Naaman's annoyance at Elisha's instruction. His servants encourage him to listen. “If I'm sick, is bathing enough?” a child asks. “No,” says the teacher. “Seek qualified medical care; this is an extraordinary faith story.”"
  ],
  "langis-balo": [
    "“Paano ko poprotektahan ang aking mga anak?” ang matinding pangamba ng biyuda habang lumalapit kay Eliseo. “Ano ang mayroon ka sa bahay?” ang diwa ng tanong ng propeta. “Kaunting langis,” ang kaniyang sagot. Mula roon nagsimula ang hindi inaasahang tulong sa salaysay.",
    "“How can I protect my children?” the widow worries as she approaches Elisha. “What do you have at home?” reflects the prophet's question. “A little oil,” she answers. From that small beginning, unexpected help unfolds in the account.",
    "“Pahiram po ng bakanteng sisidlan,” ang maaaring sinabi ng pamilya sa mga kapitbahay sa pagsasadula. Hindi nila inasahang mapupuno ang marami. “Kaya po ba nakatulong ang komunidad?” tanong ng bata. “Oo,” sagot ng guro, “mahalaga ang pagtugon kapag may pamilyang nanganganib.”",
    "“May we borrow an empty jar?” the family might ask neighbors in this dramatization. They do not expect so many to fill. “Did the community help?” a child asks. “Yes,” says the teacher. “Responding to a family in danger is important.”"
  ],
  "josiah-aklat": [
    "“May natagpuan kaming aklat sa templo,” ang balitang nakarating sa batang Haring Josias. Nang basahin ito, nakita niya ang layo ng pamumuhay ng bayan sa kanilang mga pangako. “Puwede po bang matuto ang batang pinuno?” tanong ng bata. “Oo,” sagot ng guro, “hindi hadlang ang kabataan sa pagsisikap na maging makatarungan.”",
    "“We found a book in the temple,” is the news brought to young King Josiah. When it is read, he sees how far the people have strayed from their promises. “Can a young leader learn to do better?” a child asks. “Yes,” the teacher replies. “Youth is no barrier to seeking justice.”",
    "“Pakinggan natin ang mga salita ng aklat,” ang diwa ng pagtitipon ni Josias sa bayan. Hindi niya itinago ang natuklasan. “Bakit po niya ibinahagi?” tanong ng bata. “Dahil ang pagwawasto ay mas mabuti kapag may malinaw na kaalaman at sama-samang pananagutan,” sagot ng guro.",
    "“Let us hear the words of the book,” conveys Josiah's gathering of the people. He does not keep the discovery hidden. “Why did he share it?” a child asks. “Because correction works better with clear knowledge and shared responsibility,” the teacher says."
  ],
  "esther": [
    "“Sino ang makapagsasabi kung bakit ka naroon sa pagkakataong ito?” ang diwa ng paalala ni Mordecai kay Ester. Nang malaman niya ang panganib sa kaniyang bayan, natakot siya. “Puwede po bang maging matapang kahit natatakot?” tanong ng bata. “Oo,” sagot ng guro, “kung maingat at hindi padalos-dalos.”",
    "“Who knows whether you have come to this position for such a time?” reflects Mordecai's message to Esther. When she hears of the danger to her people, she is afraid. “Can courage exist alongside fear?” a child asks. “Yes,” the teacher replies. “With careful, thoughtful action.”",
    "“Maghanda tayo at mag-ayuno,” ang diwa ng hiling ni Ester sa kaniyang mga kababayan sa salaysay. Pinag-isipan niya kung paano lalapit sa hari. “Kailangan po ba laging mag-isa kapag may mabigat na problema?” tanong ng bata. “Hindi,” sagot ng guro, “humingi ng mapagkakatiwalaang tulong.”",
    "“Prepare and fast,” conveys Esther's request to her people in the account. She thinks carefully about approaching the king. “Must we face frightening problems alone?” a child asks. “No,” the teacher says. “Seek trustworthy help.”"
  ],
  "ezra": [
    "“Pakinggan natin ang mga salita ng Kautusan,” ang diwa ng pagtitipon sa panahon ni Ezra. Hindi lang nila binigkas ang mga salita; ipinaliwanag ang kahulugan. “Bakit po kailangan pa ng paliwanag?” tanong ng bata. “Dahil hindi sapat na marinig mo ang salita kung hindi mo nauunawaan,” sagot ng guro.",
    "“Let us listen to the words of the Law,” conveys the gathering in Ezra's time. The words are not merely recited; their meaning is explained. “Why did people need an explanation?” a child asks. “Hearing without understanding is not enough,” the teacher replies.",
    "“Kung may hindi ko naiintindihan sa Biblia, puwede po ba akong magtanong?” usisa ng bata. “Siyempre,” sagot ng guro. “Magandang aral ang ipinakita ng mga nagbasa kasama ni Ezra: magbigay ng panahon sa pag-unawa, at huwag gawing dahilan ng panghuhusga ang maling pagkaintindi.”",
    "“If I don't understand something in the Bible, may I ask?” a child wonders. “Of course,” the teacher says. “The readers with Ezra model something important: make room for understanding, and never use confusion as a reason to shame someone.”"
  ],
  "nehemiah": [
    "“Sirang-sira ang mga pader ng Jerusalem,” ang balitang nagpalungkot kay Nehemias. “Ano ang maaari kong gawin?” ang kaniyang tanong sa diwa ng salaysay. Nanalangin siya at humingi ng pahintulot bago kumilos. “Bakit po muna siya nagplano?” tanong ng bata. “Upang makatutulong nang maayos,” sagot ng guro.",
    "“Jerusalem's walls are broken,” is the news that grieves Nehemiah. “What can I do?” conveys his response. He prays and seeks permission before acting. “Why did he make a plan first?” a child asks. “To help responsibly,” the teacher explains.",
    "“Ang grupong ito sa bahagi ng pader; ang iba naman doon,” ang pagsasaayos ng gawain sa pagsasadula. May mga nananakot, kaya nagbantay rin sila sa kaligtasan. “Kung may project po kami sa paaralan,” tanong ng bata, “mahalaga rin ang paghahati ng gawain?” “Oo, at walang dapat ipilit sa delikadong trabaho,” sagot ng guro.",
    "“This group works on one section; another group on the next,” is how our dramatization organizes the task. Threats arise, so safety matters too. “When we have a school project,” a child asks, “should we share the tasks?” “Yes, and nobody should be pushed into dangerous work,” the teacher answers."
  ],
  "job": [
    "“Bakit nangyayari ito sa akin?” ang bigat ng tanong ni Job sa gitna ng pagdurusa. Ang ilang kaibigan ay nagmungkahi ng madaling paliwanag at nakasakit lalo. “Mali po bang magtanong kapag nalulungkot?” tanong ng bata. “Hindi,” sagot ng guro, “at mahalagang makinig muna bago humusga.”",
    "“Why is this happening to me?” expresses Job's anguish in suffering. Some friends offer simplistic explanations that make his pain worse. “Is asking questions wrong when we are sad?” a child asks. “No,” the teacher says. “Listen before judging.”",
    "“Hindi ko lubos na nauunawaan,” ang maaaring aminin ng kaibigang natuto sa pagsasadula. Sa pagdating ng sagot ng Diyos, lumitaw kung gaano kalawak ang hindi nalalaman ng tao. “Kung may maysakit po, kasalanan niya ba agad iyon?” tanong ng bata. “Hindi,” sagot ng guro, “huwag sisihin ang naghihirap.”",
    "“I do not fully understand,” a wiser friend might admit in this dramatization. God's response shows how much human beings do not know. “If someone is sick, does that mean it is their fault?” a child asks. “No,” the teacher answers. “Never blame someone simply because they suffer.”"
  ],
  "isaiah-tawag": [
    "Sa pangitain ni Isaias, narinig ang mga serapin na pumupuri sa kabanalan ng Diyos. “Bakit po nakaramdam si Isaias ng kakulangan?” tanong ng bata. “Nakita niyang hindi siya perpekto,” paliwanag ng guro. “Ngunit ang pagkilala sa sariling pagkukulang ay maaaring simula ng pagbabago.”",
    "In Isaiah's vision, the seraphim praise God's holiness. “Why did Isaiah feel unworthy?” a child asks. “He realized he was not perfect,” the teacher explains. “Recognizing our shortcomings can be the start of change.”",
    "“Sino ang ating isusugo?” ang diwa ng tanong sa pangitain ng Isaias 6. “Narito ako, isugo Mo ako,” ang kaniyang sagot. “Maaari po bang maglingkod kahit kinakabahan?” tanong ng bata. “Oo,” sagot ng guro, “ngunit laging humingi ng tamang gabay.”",
    "“Whom shall we send?” conveys the question in Isaiah's vision. “Here I am; send me,” is his response. “Can someone serve even when nervous?” a child asks. “Yes,” says the teacher, “while seeking good guidance.”"
  ],
  "jeremiah-bata": [
    "“Bata pa ako; hindi ako marunong magsalita,” ang diwa ng pag-aalinlangan ni Jeremias. Sa mensahe ng Diyos, hindi lamang edad ang batayan ng tungkulin. “Kaya ko rin po bang magsabi ng totoo?” tanong ng bata. “Oo,” sagot ng guro, “at puwede kang humingi ng tulong kung mahirap.”",
    "“I am too young; I do not know how to speak,” conveys Jeremiah's objection. God's response does not make age the only measure of responsibility. “Can I speak the truth too?” a child asks. “Yes,” the teacher replies. “And you may ask for help when it is difficult.”",
    "“Huwag kang matakot sa kanilang mga mukha,” ang diwa ng paghikayat kay Jeremias sa kaniyang natatanging tungkulin. “Ibig sabihin po ba na hindi na ako matatakot kailanman?” tanong ng bata. “Hindi,” sagot ng guro. “Ang tapang ay pakikitungo sa takot nang may gabay at respeto.”",
    "“Do not be afraid of them,” conveys Jeremiah's encouragement for his unique calling. “Does that mean I'll never be scared?” a child asks. “No,” the teacher says. “Courage means responding to fear with guidance and respect.”"
  ],
  "daniel-pagkain": [
    "“Maaari po bang subukan namin ang ibang pagkain?” magalang na nakiusap si Daniel ayon sa diwa ng Daniel 1. Hindi siya nanlait sa pagkain ng iba. “Paano po niya ipinakita ang paninindigan?” tanong ng bata. “Sa mahinahon at malinaw na pakikipag-usap,” paliwanag ng guro.",
    "“May we try different food?” Daniel asks respectfully in the sense of Daniel 1. He does not mock other people's food. “How did he stand by his beliefs?” a child asks. “Through calm, clear communication,” the teacher explains.",
    "“Subukan natin sa loob ng takdang panahon,” ang kasunduang ginawa nila sa tagapamahala sa salaysay. “Dapat po ba nating sundan ang diyeta ni Daniel kapag may sakit tayo?” tanong ng bata. “Hindi basta-basta,” sagot ng guro. “Kumonsulta sa propesyonal at mag-ingat sa kalusugan.”",
    "“Let's try it for a set period,” conveys the arrangement made with the supervisor. “Should we copy Daniel's diet when we are ill?” a child asks. “Not automatically,” the teacher says. “Consult qualified professionals and take care of your health.”"
  ],
  "apoy-tatlong-kaibigan": [
    "“Hindi kami sasamba sa rebulto,” ang diwa ng sagot ng tatlong kaibigan sa Daniel 3. Alam nilang may panganib ang pagtanggi. “Dapat po ba nating subukan ang lakas ng loob sa apoy?” tanong ng bata. “Hinding-hindi,” sagot ng guro, “ito ay sinaunang natatanging salaysay, hindi gawain para gayahin.”",
    "“We will not worship the statue,” conveys the three friends' response in Daniel 3. They know refusal carries danger. “Should we test our courage in fire?” a child asks. “Absolutely not,” the teacher replies. “This is an extraordinary ancient account, not an action to imitate.”",
    "Namangha ang hari nang makita ang ikaapat na anyo sa hurno at ang mga kaibigang hindi nasaktan. “Ano ang dapat nating tandaan?” tanong ng bata. “Igalang ang paninindigan ng iba at huwag piliting sumamba ang tao,” sagot ng guro. “Ang pananampalataya ay hindi dahilan upang ilagay sa panganib ang buhay.”",
    "The king is astonished to see a fourth figure in the furnace and the friends unharmed. “What should we remember?” a child asks. “Respect others' convictions and never force someone to worship,” the teacher says. “Faith is never an excuse to put a life in danger.”"
  ],
  "daniel-leon": [
    "“Bawal ang panalangin maliban sa itinakda ng hari,” ang diwa ng mapanlinlang na utos laban kay Daniel. “Bakit po ginawa iyon?” tanong ng bata. “Dahil may mga pinunong nainggit sa kaniyang katapatan,” paliwanag ng guro. “Ang patakaran ay hindi dapat gamitin upang apihin ang kapwa.”",
    "“No prayers except those ordered by the king,” conveys the trap set against Daniel. “Why did they make that rule?” a child asks. “Some officials resented his integrity,” the teacher explains. “Rules must never become tools of oppression.”",
    "“Daniel, nailigtas ka ba ng iyong Diyos?” ang diwa ng tanong ng hari pagkabukas ng lungga sa Daniel 6. Ayon sa salaysay, iniligtas siya. “Puwede po bang lumapit sa leon para subukan ang pananampalataya?” tanong ng bata. “Hindi kailanman,” sagot ng guro, “umiwas sa mababangis na hayop.”",
    "“Daniel, has your God rescued you?” conveys the king's question at the den in Daniel 6. The account says Daniel was saved. “Should we go near lions to test faith?” a child asks. “Never,” the teacher answers. “Stay away from dangerous wild animals.”"
  ],
  "ezekiel-buto": [
    "“Mabubuhay pa kaya ang tuyong mga butong ito?” ang diwa ng tanong sa pangitain ni Ezekiel. “Panginoon, Ikaw ang nakaaalam,” ang mapagpakumbabang tugon ng propeta. “Bakit po buto ang larawan?” tanong ng bata. “Upang ipakita kung gaano kawalang-pag-asa ang naramdaman ng bayan,” sagot ng guro.",
    "“Can these dry bones live?” conveys the question in Ezekiel's vision. “Lord, You know,” is the prophet's humble response. “Why use bones as the picture?” a child asks. “To show how hopeless the people felt,” the teacher explains.",
    "Nang mabuo muli ang mga buto at magkaroon ng hininga sa pangitain, ipinaliwanag ng Diyos ang pag-asa para sa Kaniyang bayan. “Totoo po bang larawan ito?” tanong ng bata. “Oo, pangitain ito ng muling pagbangon,” sagot ng guro. “Hindi ito kuwento upang takutin ang mga batang nakikinig.”",
    "As bones come together and receive breath in the vision, God explains the promise of renewal for the people. “Is it a picture with a meaning?” a child asks. “Yes, it is a vision of restoration,” the teacher says. “It is not meant to frighten children.”"
  ],
  "hosea-habag": [
    "“Parang magulang na nagtuturo sa batang maglakad,” ang larawang ginamit sa mensahe ni Oseas upang ipaliwanag ang habag ng Diyos. “Paano po kapag nadapa ang bata?” tanong ng nakikinig. “Inaalalayan siya at tinutulungang matuto,” sagot ng guro, “hindi iniiwan sa takot.”",
    "“Like a parent teaching a child to walk,” is the picture in Hosea's message about God's compassion. “What happens when the child falls?” a listener asks. “The child is helped to stand and learn,” the teacher says, “not abandoned in fear.”",
    "“Kahit paulit-ulit silang lumayo, may malasakit ang Diyos,” ang diwa ng mensahe ng propeta. “Ibig sabihin po ba na puwedeng patuloy na manakit nang walang pagbabago?” tanong ng bata. “Hindi,” sagot ng guro, “ang pag-ibig ay nagtuturo rin ng pananagutan at pagtalikod sa mali.”",
    "“Even when the people wandered, God still cared,” conveys the prophet's message. “Does that mean someone can keep harming others without changing?” a child asks. “No,” the teacher says. “Love also calls for responsibility and turning away from wrongdoing.”"
  ],
  "micah-katarungan": [
    "“Ano ang tunay na nais ng Diyos?” ang tanong na sinagot sa mensahe ni Mikas. Hindi sapat ang magarbong handog kung may inaaping kapwa. “Gumawa ng katarungan, umibig sa kabutihan, at lumakad nang mapagpakumbaba,” ang diwa ng Mikas 6:8. “Kaya dapat po patas tayo?” tanong ng bata.",
    "“What does God truly ask?” is the question answered in Micah's message. Impressive offerings are not enough if people mistreat others. “Act justly, love mercy, and walk humbly,” conveys Micah 6:8. “So we should be fair?” a child asks.",
    "“Kung may kaklaseng hindi pinapansin, ano ang puwede kong gawin?” tanong ng bata. “Anyayahan siyang sumali, pakinggan siya, at humingi ng tulong kapag may pang-aapi,” sagot ng guro. “Iyan ang paraan upang ang aral ng katarungan ay hindi lang magandang salita sa paaralan.”",
    "“What can I do if someone in class is being left out?” a child asks. “Invite them to join, listen to them, and ask for help if anyone is bullied,” the teacher replies. “That makes justice more than a nice word at school.”"
  ],
  "habakkuk-tiwala": [
    "“Hanggang kailan, Panginoon?” ang diwa ng tanong ni Habakuk nang makita ang karahasan at kawalan ng katarungan. Hindi niya itinago ang kaniyang pagkalito. “Maaari po bang magsabi sa Diyos kapag may mabigat na tanong?” usisa ng bata. “Oo,” sagot ng guro, “mahalaga ang tapat na panalangin at pakikinig.”",
    "“How long, Lord?” conveys Habakkuk's question as he sees violence and injustice. He does not hide his confusion. “May we tell God about difficult questions?” a child asks. “Yes,” says the teacher. “Honest prayer and listening matter.”",
    "“Kahit hindi mamunga ang puno,” ang diwa ng awit ni Habakuk sa huli, “patuloy akong aasa sa Diyos.” “Kung mahirap pa rin po ang buhay, kailangan bang magkunwaring masaya?” tanong ng bata. “Hindi,” sagot ng guro. “Maaaring magtiwala habang humihingi rin ng tunay na tulong.”",
    "“Even if the trees bear no fruit,” conveys Habakkuk's final song, “I will still hope in God.” “If life is still difficult, must I pretend to be happy?” a child asks. “No,” the teacher answers. “You may hold onto faith while asking for real help.”"
  ]
};
